// lib/models/user.dart — the library
import 'package:json_annotation/json_annotation.dart';
import 'address.dart';        // the part file cannot import this itself

part 'user.g.dart';           // ✅ you write this; the generator never adds it

@JsonSerializable()
class User {
  const User({required this.id, required this.name, this.address});

  final int id;
  final String name;
  final Address? address;

  // the generated helpers are library-private — only a part can reach them
  factory User.fromJson(Map<String, dynamic> json) => _$UserFromJson(json);
  Map<String, dynamic> toJson() => _$UserToJson(this);
}

