// ── includeIfNull: drop the key, or send an explicit null ────────
@JsonSerializable(includeIfNull: false)
class PatchProfile {
  const PatchProfile({this.nickname, this.avatarUrl});

  final String? nickname;          // absent → server leaves it alone
  @JsonKey(includeIfNull: true)    // ✅ null here means "clear the avatar"
  final String? avatarUrl;

  Map<String, dynamic> toJson() => _$PatchProfileToJson(this);
}

class Money {
  const Money(this.minorUnits, this.currency);
  final int minorUnits;
  final String currency;
}

// const constructor: the annotation itself is a const instance
class MoneyConverter implements JsonConverter<Money, Map<String, dynamic>> {
  const MoneyConverter();
  @override
  Money fromJson(Map<String, dynamic> json) =>
      Money(json['amount'] as int, json['currency'] as String);
  @override
  Map<String, dynamic> toJson(Money m) =>
      {'amount': m.minorUnits, 'currency': m.currency};
}

class EpochMillis implements JsonConverter<DateTime, int> {
  const EpochMillis();
  @override
  DateTime fromJson(int json) =>
      DateTime.fromMillisecondsSinceEpoch(json, isUtc: true);
  @override
  int toJson(DateTime d) => d.toUtc().millisecondsSinceEpoch;
}

// ✅ a nullable field needs its own converter — the match is on the exact type
class EpochMillisOrNull implements JsonConverter<DateTime?, int?> {
  const EpochMillisOrNull();
  @override
  DateTime? fromJson(int? json) => json == null
      ? null
      : DateTime.fromMillisecondsSinceEpoch(json, isUtc: true);
  @override
  int? toJson(DateTime? d) => d?.toUtc().millisecondsSinceEpoch;
}

@JsonSerializable(converters: [MoneyConverter(), EpochMillis()])
class Invoice {
  const Invoice({
    required this.total,
    required this.lines,
    required this.createdAt,
    this.paidAt,
  });

  final Money total;            // ✅ MoneyConverter, from the class list
  final List<Money> lines;      // ✅ same converter, applied per element
  final DateTime createdAt;     // ✅ EpochMillis
  @EpochMillisOrNull()          // ❌ without this: cast error on a null
  final DateTime? paidAt;

  factory Invoice.fromJson(Map<String, dynamic> json) => _$InvoiceFromJson(json);
}

@JsonSerializable(checked: true)
class Profile {
  const Profile({required this.name, required this.age, this.bio = ''});

  final String name;

  @JsonKey(fromJson: _age)       // ✅ 30, 30.0 and "30" all land as int
  final int age;

  @JsonKey(defaultValue: '')     // ✅ absent or null → ''
  final String bio;

  factory Profile.fromJson(Map<String, dynamic> json) => _$ProfileFromJson(json);
}

int _age(Object? v) => switch (v) {
      int n => n,
      num n => n.toInt(),
      String s => int.tryParse(s) ?? 0,
      _ => 0,
    };

// ── checked: false (default) — bare casts, anonymous failures ──
// Profile _$ProfileFromJson(Map<String, dynamic> json) => Profile(
//       name: json['name'] as String,   // ❌ TypeError, no key in the message
//       age: json['age'] as int,        // ❌ throws on "30" and on 30.0
//     );

// ── checked: true — the failure names the class and the field ──
// Profile _$ProfileFromJson(Map<String, dynamic> json) =>
//     $checkedCreate('Profile', json, ($checkedConvert) => Profile(
//           name: $checkedConvert('name', (v) => v as String),
//           age: $checkedConvert('age', (v) => _age(v)),
//         ));

// ── one guard, at the boundary, not in a widget ───────────────
Future<Profile> fetchProfile() async {
  final res = await _dio.get('/me');
  try {
    return Profile.fromJson(res.data as Map<String, dynamic>);
  } on CheckedFromJsonException catch (e) {
    log.warn('parse failed at ${e.className}.${e.key}', e.innerError);
    throw const ContractError('profile');
  }
}

