import 'package:freezed_annotation/freezed_annotation.dart';

part 'user.freezed.dart';   // copyWith, ==, hashCode, toString
part 'user.g.dart';         // fromJson/toJson, from json_serializable

@freezed
abstract class User with _$User {        // freezed 3: abstract is required
  const factory User({
    required String id,
    required String name,
    @Default(false) bool isAdmin,
    @JsonKey(name: 'avatar_url') String? avatarUrl,
  }) = _User;

  factory User.fromJson(Map<String, dynamic> json) => _$UserFromJson(json);
}

// ── roughly what user.freezed.dart contains ──────────────────────
// mixin _$User {
//   String get id;
//   String get name;
//   bool get isAdmin;
//   String? get avatarUrl;
//   $UserCopyWith<User> get copyWith => ...;
//
//   @override bool operator ==(Object other) => identical(this, other) ||
//       (other is User && other.id == id && other.name == name &&
//        other.isAdmin == isAdmin && other.avatarUrl == avatarUrl);
//   @override int get hashCode => Object.hash(runtimeType, id, name, ...);
//   @override String toString() => 'User(id: $id, name: $name, ...)';
// }
//
// class _User ...  the concrete class behind `= _User`
// abstract class $UserCopyWith<$Res> {
//   $Res call({String id, String name, bool isAdmin, String? avatarUrl});
// }

// ── the cheap version, for something you only ever decode ────────
@JsonSerializable()
class UserDto {                          // one builder, no copyWith, no ==
  const UserDto({required this.id, required this.name});
  final String id;
  final String name;
  factory UserDto.fromJson(Map<String, dynamic> json) => _$UserDtoFromJson(json);
}

// ── Hand-written: no build step, exhaustive by construction ───────
sealed class LoadState {
  const LoadState();
}

final class Idle extends LoadState { const Idle(); }
final class Loading extends LoadState { const Loading(); }

final class Loaded extends LoadState {
  const Loaded(this.items);
  final List<Item> items;

  // ❌ yours to maintain: forget these and every emit rebuilds the screen
  @override
  bool operator ==(Object o) => o is Loaded && listEquals(o.items, items);
  @override
  int get hashCode => Object.hashAll(items);
}

String label(LoadState s) => switch (s) {   // adding a variant breaks this
      Idle() => 'idle',
      Loading() => 'loading',
      Loaded(:final items) => '${items.length} items',
    };

// ── freezed: the same switch, plus ==, copyWith and JSON ──────────
@Freezed(
  unionKey: 'type',
  unionValueCase: FreezedUnionCase.snake,
  fallbackUnion: 'unknown',       // a value this build has never seen
)
sealed class Event with _$Event {           // freezed 3: sealed for unions
  const factory Event.purchase({
    required String sku,
    required int cents,
  }) = Purchase;
  const factory Event.screenView({required String route}) = ScreenView;
  const factory Event.unknown() = UnknownEvent;

  factory Event.fromJson(Map<String, dynamic> json) => _$EventFromJson(json);
}

void handle(Event e) {
  final line = switch (e) {                 // same shape as the sealed version
    Purchase(:final cents) => 'paid $cents',
    ScreenView(:final route) => 'saw $route',
    UnknownEvent() => 'ignored',
  };
  // and the parts Dart alone does not hand you:
  final free = e is Purchase ? e.copyWith(cents: 0) : e;
  queue.add(free.toJson());
  log.info(line);
}

