import 'package:analyzer/dart/element/element.dart';
import 'package:build/build.dart';
import 'package:source_gen/source_gen.dart';
import 'package:my_annotations/my_annotations.dart'; // class AnalyticsEvent

class EventGenerator extends GeneratorForAnnotation<AnalyticsEvent> {
  @override
  String generateForAnnotatedElement(
    Element element,
    ConstantReader annotation,
    BuildStep buildStep,
  ) {
    if (element is! ClassElement) {
      // ✅ reported at the annotation's own file:line, not as broken output
      throw InvalidGenerationSourceError(
        '@AnalyticsEvent can only annotate a class.',
        element: element,
      );
    }

    // ConstantReader reads the evaluated constant — non-const args throw here
    final eventName = annotation.read('name').stringValue;
    final fields = element.fields.where((f) => !f.isStatic && !f.isPrivate);

    final entries = fields.map((f) => "'${f.name}': ${f.name}").join(', ');

    // an extension adds behaviour without the class having to `with` anything
    return '''
extension \$${element.name}Payload on ${element.name} {
  String get eventName => '$eventName';
  Map<String, Object?> get payload => {$entries};
}
''';
  }
}

// the factory build.yaml points at — must be top level
Builder analyticsBuilder(BuilderOptions options) =>
    SharedPartBuilder([EventGenerator()], 'analytics');

