// user.dart
import 'package:json_annotation/json_annotation.dart';
part 'user.g.dart';

@JsonSerializable()
class User {
  const User({required this.id, required this.name});
  final String id;
  final String name;

  // you hand-write these two forwarders in every model, forever
  factory User.fromJson(Map<String, dynamic> json) => _$UserFromJson(json);
  Map<String, dynamic> toJson() => _$UserToJson(this);
}

// user.g.dart (generated): private free functions. Nothing is added to User,
// which is why the forwarders above have to exist at all.
part of 'user.dart';

User _$UserFromJson(Map<String, dynamic> json) =>
    User(id: json['id'] as String, name: json['name'] as String);
Map<String, dynamic> _$UserToJson(User i) => {'id': i.id, 'name': i.name};

// freezed stacks a second layer on this: `class User with _$User`, plus a
// redirecting factory to a generated `_User` subclass you never name.

// ── With augmentations: the part adds the members to your class ──────────
// user.dart
@JsonSerializable()
class User {
  const User({required this.id, required this.name});
  final String id;
  final String name;
  // no forwarders, no `with _$User`
}

// user.g.dart (generated)
part of 'user.dart';

augment class User {
  factory User.fromJson(Map<String, dynamic> json) =>
      User(id: json['id'] as String, name: json['name'] as String);
  Map<String, dynamic> toJson() => {'id': id, 'name': name};
}

